class Solution:
    def shortestPush(self, gains: List[int], target: int) -> int:
        n, best = len(gains), 0
        for i in range(n):
            total = 0
            for j in range(i, n):
                total += gains[j]
                if total >= target:
                    if best == 0 or j - i + 1 < best:
                        best = j - i + 1
                    break
        return best

