class Solution:
    def shortestPush(self, gains: List[int], target: int) -> int:
        left = total = 0
        best = len(gains) + 1
        for i, g in enumerate(gains):
            total += g
            while total >= target:
                best = min(best, i - left + 1)
                total -= gains[left]
                left += 1
        return best if best <= len(gains) else 0

