class Solution {
    public int shortestPush(int[] gains, int target) {
        int n = gains.length, left = 0, best = n + 1;
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += gains[i];
            while (total >= target) {
                best = Math.min(best, i - left + 1);
                total -= gains[left++];
            }
        }
        return best <= n ? best : 0;
    }
}

